type targetTypeScriptable =
    | {
          /** @deprecated The type of target being requested */
          target_type: 'sys_script_include' | 'scriptable'
          targetType?: never
      }
    | {
          /** The type of target being requested */
          targetType: 'sys_script_include' | 'scriptable'
          target_type?: never
      }

type targetTypeSysDbObject =
    | {
          /** @deprecated The type of target being requested */
          target_type: 'sys_db_object'
          targetType?: never
      }
    | {
          /** The type of target being requested */
          targetType: 'sys_db_object'
          target_type?: never
      }

type targetTypeAndOperation =
    | ({
          /** The operation being requested on the target. */
          operation: 'execute'
      } & targetTypeScriptable)
    | ({
          /** The operation being requested on the target. */
          operation: 'create' | 'read' | 'write' | 'delete'
      } & targetTypeSysDbObject)

type targetScope =
    | {
          /** @deprecated The application scope whose resources are being requested. */
          target_scope: string
          targetScope?: never
      }
    | {
          /** The application scope whose resources are being requested. */
          targetScope: string
          target_scope?: never
      }

type targetName =
    | {
          /** @deprecated The name of the table, script include, or script object being requested. */
          target_name: string
          targetName?: never
      }
    | {
          /** The name of the table, script include, or script object being requested. */
          targetName: string
          target_name?: never
      }

type CrossScopePrivilegeType = {
    /** The authorization status of the privilege request. Can be 'requested', 'allowed', or 'denied'. */
    status: 'requested' | 'allowed' | 'denied'
} & targetTypeAndOperation &
    targetScope &
    targetName

type CrossScopePrivilege = Now.Internal.WithID<CrossScopePrivilegeType & Now.Internal.Meta>

/**
 * Creates a Cross Scope Privilege record (`sys_scope_privilege`).
 *
 * @see https://docs.servicenow.com/csh?topicname=c_CrossScopePrivilegeRecord.html&version=latest
 *
 * @param config - an object containing the following properties:
 *   * **$id** - unique id for the record, typically using `Now.ID["value"]`
 *   * **operation** - operation the script performs on the target
 *   * **status** - authorization for this record
 *   * **targetName** - name of the table, script include, or script object being requested
 *   * **targetScope** - application whose resources are being requested
 *   * **targetType** - type of request
 */
export function CrossScopePrivilege(config: CrossScopePrivilege) {
    return config
}
